const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const IDS = [
  'elements-zimmdrawer--small',
  'elements-zimmdrawer--large',
  'elements-zimmdrawer--x-large',
  'elements-zimmdrawer--with-title-large',
  'elements-zimmdrawer--with-title-small-drawer',
];

(async () => {
  const browser = await chromium.launch();
  for (const id of IDS) {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await page.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`, { waitUntil: 'domcontentloaded', timeout: 30000 });
    try {
      await page.waitForSelector('[role="dialog"]', { timeout: 8000 });
    } catch (e) {
      console.log(`${id}: NO DIALOG FOUND — ${e.message}`);
      await page.close();
      continue;
    }
    await page.waitForTimeout(400);
    const info = await page.evaluate(() => {
      const dialog = document.querySelector('[role="dialog"]');
      if (!dialog) return null;
      const first = dialog.firstElementChild;
      if (!first) return { note: 'dialog has no children' };
      const cs = getComputedStyle(first);
      return {
        firstChildTag: first.tagName,
        childCount: first.children.length,
        position: cs.position,
        hasCloseButton: !!first.querySelector('button[aria-label="Close" i]'),
        outerHTMLStart: first.outerHTML.slice(0, 300),
      };
    });
    console.log(`--- ${id} ---`);
    console.log(JSON.stringify(info, null, 2));
    await page.close();
  }
  await browser.close();
})();
