const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const targets = [
  { id: 'layout-zimmcountrylanguagemismatch--location', vp: { width: 390, height: 844 }, tag: 'location-390' },
  { id: 'layout-zimmcountrylanguagemismatch--location', vp: { width: 834, height: 1112 }, tag: 'location-834' },
  { id: 'layout-zimmcountrylanguagemismatch--location', vp: { width: 1440, height: 900 }, tag: 'location-1440' },
  { id: 'elements-zimmdrawer--small', vp: { width: 390, height: 844 }, tag: 'small-390' },
  { id: 'elements-zimmdrawer--large', vp: { width: 390, height: 844 }, tag: 'large-390' },
  { id: 'elements-zimmdrawer--x-large', vp: { width: 390, height: 844 }, tag: 'xlarge-390' },
  // Substitutes — the literally-requested small/large stories above never render a `header`
  // part at all (see prior probe: position:absolute, childCount:1 = floating closeButton, not
  // header). These two DO render the real header row (position:static, childCount:2) and are
  // the closest existing proxy for what HEADER_HEIGHT_MOBILE actually looks like rendered.
  { id: 'elements-zimmdrawer--with-title-small-drawer', vp: { width: 390, height: 844 }, tag: 'proxy-small-with-title-390' },
  { id: 'elements-zimmdrawer--with-title-large', vp: { width: 390, height: 844 }, tag: 'proxy-large-with-title-390' },
];

(async () => {
  const browser = await chromium.launch();
  const results = [];

  for (const t of targets) {
    const page = await browser.newPage({ viewport: t.vp });
    const errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await page.goto(`http://localhost:6006/iframe.html?id=${t.id}&viewMode=story`, {
      waitUntil: 'domcontentloaded',
      timeout: 30000,
    });

    let dialogFound = true;
    try {
      await page.waitForSelector('[role="dialog"]', { timeout: 8000 });
    } catch (e) {
      dialogFound = false;
    }
    await page.waitForTimeout(500); // let framer-motion enter transition finish (300ms) + settle

    if (!dialogFound) {
      results.push({ ...t, error: 'NO DIALOG RENDERED', errors });
      const shotPath = `/tmp/a5-shots/${t.tag}__NO-DIALOG.png`;
      await page.screenshot({ path: shotPath });
      await page.close();
      continue;
    }

    const measurement = await page.evaluate(() => {
      const dialog = document.querySelector('[role="dialog"]');
      const first = dialog.firstElementChild;
      const cs = getComputedStyle(first);
      const rect = first.getBoundingClientRect();
      const isHeaderPart = cs.position !== 'absolute';
      return {
        isHeaderPart,
        position: cs.position,
        childCount: first.children.length,
        height: rect.height,
        width: rect.width,
        top: rect.top,
        left: rect.left,
        paddingTop: cs.paddingTop,
        paddingBottom: cs.paddingBottom,
        paddingLeft: cs.paddingLeft,
        paddingRight: cs.paddingRight,
        backgroundColor: cs.backgroundColor,
        outerHTMLStart: first.outerHTML.slice(0, 200),
        dialogRect: dialog.getBoundingClientRect(),
      };
    });

    const shotPath = `/tmp/a5-shots/${t.tag}.png`;
    await page.screenshot({ path: shotPath });

    results.push({ ...t, measurement, shotPath, errors });
    await page.close();
  }

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
})();
